mapper.select:
SELECT family_id, user_id, family_name, relation, birth_date
FROM family
WHERE family_id = #{familyId}

SELECT deduction_limit_id, relation, is_minor, deduction_limit, effective_from, effective_to
FROM gift_deduction_limit
WHERE relation = #{relation}
  AND is_minor = #{minor}
  AND effective_from <= #{asOfDate}
  AND (effective_to IS NULL OR effective_to > #{asOfDate})
ORDER BY effective_from DESC
LIMIT 1

SELECT
    COALESCE(SUM(amount), 0) AS completed_amount,
    MIN(gift_date) AS oldest_gift_date
FROM gift
WHERE family_id = #{familyId}
  AND status = 'COMPLETED'
  AND gift_date >= #{windowStart}
  AND gift_date < #{asOfDate}

SELECT gift_id, amount, gift_date
FROM gift
WHERE family_id = #{familyId}
  AND status = 'COMPLETED'
  AND gift_date >= #{windowStart}
  AND gift_date < #{asOfDate}
ORDER BY gift_date, gift_id

mapper.update:
UPDATE simulation_result
SET expected_future_value = #{expectedFutureValue},
    risk_profile = #{riskProfile}
WHERE result_id = #{resultId}
